use std::path::Path;

pub fn safe_file_part(value: &str) -> String { let value = value.chars().map(|ch| if matches!(ch, '<' | '>' | ':' | '"' | '/' | '\\' | '|' | '?' | '*') { '_' } else { ch }).collect::<String>(); let value = value.trim_matches(|ch: char| ch == '.' || ch.is_whitespace()); if value.is_empty() { "未知".into() } else { value.into() } }
pub fn download_file_name(name: &str, artists: &[String], url: &str) -> String { let extension = url.split('?').next().and_then(|path| path.rsplit('.').next()).filter(|ext| (1..=5).contains(&ext.len()) && ext.chars().all(|ch| ch.is_ascii_alphanumeric())).unwrap_or("mp3"); format!("{} - {}.{}", safe_file_part(name), safe_file_part(&artists.join("、")), extension) }
pub fn ensure_audio_response(status: u16, content_type: Option<&str>) -> Result<(), String> { if !(200..300).contains(&status) { return Err(format!("音频下载失败（CDN HTTP {status}）")); } if content_type.is_some_and(|value| value.to_ascii_lowercase().contains("text/html")) { return Err("音频下载失败：CDN 返回了网页而不是音频".into()); } Ok(()) }
pub async fn stream_to_file(client: &reqwest::Client, url: &str, path: &Path) -> Result<(), String> { let response = client.get(url).header("Referer", "https://music.163.com/").send().await.map_err(|e| e.to_string())?; let status = response.status().as_u16(); let content_type = response.headers().get("content-type").and_then(|value| value.to_str().ok()).map(|value| value.to_owned()); ensure_audio_response(status, content_type.as_deref())?; let mut file = tokio::fs::File::create(path).await.map_err(|e| e.to_string())?; use futures_util::StreamExt; use tokio::io::AsyncWriteExt; let mut stream = response.bytes_stream(); while let Some(chunk) = stream.next().await { file.write_all(&chunk.map_err(|e| e.to_string())?).await.map_err(|e| e.to_string())?; } file.flush().await.map_err(|e| e.to_string())?; Ok(()) }
